const $=s=>document.querySelector(s);let state,dirty=false,picker;
async function api(body){const r=await fetch('/api/admin',body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{cache:'no-store'});const data=await r.json();if(!r.ok){if(r.status===401&&state)showLogin();throw Error(data.error||'Der opstod en fejl.');}return data;}
function message(text,error=false){$('#message').textContent=text;$('#message').classList.toggle('error',error);}
function changed(){dirty=true;$('#dirty').textContent='Du har ændringer, der ikke er gemt';$('#save').disabled=false;}
function showLogin(){$('#dashboard').hidden=true;$('#logout').hidden=true;$('#login').hidden=false;state=null;dirty=false;}
async function load(){try{state=await api();$('#login').hidden=true;$('#dashboard').hidden=false;$('#logout').hidden=false;const defaults=await fetch('/admin/fields.json').then(r=>r.json());$('#text-fields').replaceChildren();for(const field of defaults){const label=document.createElement('label');label.textContent=field.label;const input=document.createElement('textarea');input.value=state.texts[field.key];input.maxLength=6000;input.rows=Math.min(10,Math.max(2,Math.ceil(input.value.length/90)));input.addEventListener('input',()=>{state.texts[field.key]=input.value;changed();});label.append(input);$('#text-fields').append(label);}renderClosed();await renderImages();dirty=false;$('#dirty').textContent='Ingen ændringer';$('#save').disabled=true;}catch(e){showLogin();message(e.message,!e.message.startsWith('Log ind'));}}
function renderClosed(){
 for(const [field,id,empty] of [['blocked','#closed-list','Ingen ekstra lukkede dage. Søndag, mandag og tirsdag er stadig lukket som standard.'],['opened','#opened-list','Ingen ekstra åbne dage.']]){
 const root=$(id);root.replaceChildren();const dates=[...new Set([...state[field].tapas,...state[field].sandwich])].sort();if(!dates.length){root.textContent=empty;continue;}
 for(const date of dates){const row=document.createElement('div');row.className='closed-row';const info=document.createElement('span');info.textContent=new Date(date+'T12:00:00').toLocaleDateString('da-DK',{day:'numeric',month:'long',year:'numeric'});row.append(info);
 for(const kind of ['tapas','sandwich'].filter(k=>state[field][k].includes(date))){const button=document.createElement('button');button.type='button';button.textContent=(field==='blocked'?'Åbn ':'Fjern ekstra åbning for ')+kind;button.addEventListener('click',()=>{state[field][kind]=state[field][kind].filter(d=>d!==date);if(field==='blocked'&&[0,1,2].includes(new Date(date+'T12:00:00Z').getUTCDay()))state.opened[kind]=[...new Set([...state.opened[kind],date])];changed();renderClosed();});row.append(button);}root.append(row);}}
}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{const f=new FormData(e.target);await api({action:'login',username:f.get('username'),password:f.get('password')});e.target.reset();message('Du er logget ind.');await load();}catch(e){message(e.message,true);}finally{button.disabled=false;}});
$('#logout').addEventListener('click',async()=>{if(uploading){message('Vent til billedet er uploadet.',true);return;}if(dirty&&!confirm('Du har ikke gemt dine ændringer. Log ud alligevel?'))return;try{await api({action:'logout'});showLogin();message('Du er logget ud.');}catch(e){message(e.message,true);}});
$('#save').addEventListener('click',async()=>{if(uploading)return;const button=$('#save');button.disabled=true;try{const result=await api({action:'save',...state});state.revision=result.revision;dirty=false;$('#dirty').textContent='Alle ændringer er gemt';message('Gemt. Ændringerne vises nu på hjemmesiden.');}catch(e){message(e.message,true);button.disabled=false;} });
function applyDates(open){const dates=picker.selectedDates.map(d=>picker.formatDate(d,'Y-m-d'));if(!dates.length){message('Vælg mindst én dato.',true);return;}const kinds=$('#kind').value==='both'?['tapas','sandwich']:[$('#kind').value];for(const kind of kinds){const target=open?'opened':'blocked',opposite=open?'blocked':'opened';state[target][kind]=[...new Set([...state[target][kind],...dates])].sort();state[opposite][kind]=state[opposite][kind].filter(d=>!dates.includes(d));}changed();renderClosed();picker.clear();message('Datoerne er ændret. Tryk på Gem ændringer.');}
$('#add-dates').addEventListener('click',()=>applyDates(false));
$('#open-dates').addEventListener('click',()=>applyDates(true));
$('#password-form').addEventListener('submit',async e=>{e.preventDefault();if(dirty){message('Gem først dine ændringer til hjemmesiden.',true);return;}const f=new FormData(e.target);if(f.get('password')!==f.get('repeat')){message('De nye adgangskoder er ikke ens.',true);return;}e.submitter.disabled=true;try{await api({action:'password',current:f.get('current'),password:f.get('password'),revision:state.revision});e.target.reset();showLogin();message('Adgangskoden er ændret. Log ind med den nye kode.');}catch(e){message(e.message,true);}finally{e.target.querySelector('button').disabled=false;}});
window.addEventListener('beforeunload',e=>{if(dirty||uploading){e.preventDefault();e.returnValue='';}});
const pageNames={dates:'Kalender',texts:'Tekster',security:'Adgangskode',images:'Billeder'};
const activePage=({'kalender':'dates','tekster':'texts','kode':'security','billeder':'images'})[location.pathname.split('/').filter(Boolean)[1]]||'dates';
for(const id of Object.keys(pageNames))$('#'+id).hidden=id!==activePage;
$('#page-title').textContent=pageNames[activePage];document.title=pageNames[activePage]+' · Osteporten Admin';
$('.save-bar').hidden=activePage==='security';
document.querySelectorAll('nav [data-page]').forEach(a=>{if(a.dataset.page===activePage)a.setAttribute('aria-current','page');});
let uploading=false;
async function renderImages(){if(activePage!=='images')return;const catalog=await fetch('/admin/images.json').then(r=>r.json());const root=$('#image-fields');root.replaceChildren();
for(const item of catalog){const card=document.createElement('article');card.className='image-card';const title=document.createElement('h3');title.textContent=item.label;const image=document.createElement('img');image.alt=item.label;image.loading='lazy';image.src=state.images[item.id]?'/api/image?id='+item.id+'&v='+state.revision:item.src;const label=document.createElement('label');label.textContent='Vælg nyt billede';const input=document.createElement('input');input.type='file';input.accept='image/jpeg,image/png,image/webp,image/gif';label.append(input);const status=document.createElement('p');status.className='hint';status.setAttribute('role','status');const restore=document.createElement('button');restore.type='button';restore.textContent='Gendan original';restore.disabled=!state.images[item.id];
restore.addEventListener('click',()=>{if(uploading)return;delete state.images[item.id];image.src=item.src;restore.disabled=true;status.textContent='Originalen vises efter du gemmer.';changed();});
input.addEventListener('change',async()=>{const file=input.files[0];if(!file)return;if(uploading){status.textContent='Vent til den anden upload er færdig.';input.value='';return;}if(file.size>2*1024*1024){status.textContent='Billedet må højst fylde 2 MB.';input.value='';return;}uploading=true;input.disabled=true;$('#save').disabled=true;status.textContent='Uploader billede …';try{const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Filen kunne ikke læses.'));reader.readAsDataURL(file);});const result=await api({action:'upload',id:item.id,base64,revision:state.revision});state.images[item.id]=result.path;image.src=URL.createObjectURL(file);restore.disabled=false;changed();status.textContent='Uploadet. Tryk på Gem ændringer for at vise det på hjemmesiden.';}catch(e){status.textContent=e.message;message(e.message,true);}finally{uploading=false;input.disabled=false;input.value='';$('#save').disabled=!dirty;}});
card.append(title,image,label,restore,status);root.append(card);}}

picker=flatpickr('#date-picker',{locale:'da',mode:'multiple',dateFormat:'Y-m-d',altInput:true,altFormat:'j. F Y',minDate:'today',disableMobile:true});load();

